        body: `地球は球体なので、どんな方法で平面に写しても必ずゆがみが出る。図法とは「何を正しく保つか」を選んだ結果である。

■ メルカトル図法（正角図法）
・正しいもの……角度。地図上で測った方位角のとおりに進めば目的地に着く（等角航路）。
・ゆがむもの……面積と距離。高緯度になるほど東西方向に大きく引きのばされる。
・見分け方……緯線と経線がすべて直線で、どこでも直角に交わる。緯線の間隔が高緯度ほど広がる。
・用途……海図（船の航海図）。
例）グリーンランドが南アメリカ大陸と同じくらいの大きさに描かれる。実際はグリーンランド約217万km²、南アメリカ大陸約1,780万km²で8倍以上の差がある。

■ モルワイデ図法（正積図法）
・正しいもの……面積の比。
・ゆがむもの……形。特に周辺部が大きくゆがむ。
・見分け方……全体が楕円形で、経線が中央経線以外は曲線になる。
・用途……人口・農産物の分布図など、面積の比較が意味を持つ統計地図。
※モルワイデ図法の海洋部分を切り取って陸地のゆがみを減らしたものがグード図法（ホモロサイン図法）で、これも正積である。

■ 正距方位図法
・正しいもの……図の中心からの距離と方位。
・ゆがむもの……中心以外の2点間の距離・方位・面積・形。外周に近いほど極端にゆがむ。
・見分け方……円形で、中心から放射状に方位が広がる。
・用途……航空図。国連旗のデザインもこの図法（北極中心）。

★ ポイント：「メルカトル＝角度・海図」「モルワイデ＝面積・分布図」「正距方位＝距離と方位・航空図」の三対で覚える。`,
