        body: `入試でいちばん差がつくのは「2地点の最短経路はどれか」という問題である。

■ 最短経路とは
球面上の2点を結ぶ最短の道は、その2点と地球の中心を通る平面が地球を切ったときの円（大円）の一部で、これを大圏航路という。

■ 正距方位図法で読む
図の中心から引いた直線が、そのまま最短経路になる。だから「東京を中心とする正距方位図法」が与えられていれば、東京から任意の都市への最短経路と方位・距離は定規1本で読み取れる。
例）東京を中心とした正距方位図法でロンドンへ直線を引くと、その線はシベリア上空を通る。実際の航空路もほぼその経路をとる。

■ メルカトル図法で読むと間違える
メルカトル図法で東京とロンドンを直線で結ぶと、ユーラシア大陸を東西にまっすぐ横断する線になる。しかしこれは等角航路であって最短ではない。最短経路をメルカトル図法上に描くと、北へふくらんだ曲線になる。北半球の2地点なら「北へふくらむ」、南半球どうしなら「南へふくらむ」と覚えておく。

■ 正距方位図法の外周
中心から最も遠い地点は、地球のちょうど裏側（対せき点）である。正距方位図法の円周は、この1点が円に引きのばされたものである。したがって図の外周付近の陸地は、実際とかけ離れた形になる。
例）東京中心の正距方位図法なら、外周はブラジル沖の南大西洋あたりを表す。

■ 対せき点の求め方
緯度……北緯と南緯を入れかえ、数値はそのまま。
経度……東経と西経を入れかえ、180から引いた値。
例）東京（北緯35.7度・東経139.8度）の対せき点は、南緯35.7度・西経40.2度（180−139.8＝40.2）。

⚠ 注意：「距離が正しい」は正距方位図法でも“中心からの距離だけ”である。中心を通らない2地点間の距離を図から測ってはいけない。`,
