        body: `地球は西から東へ自転しているため、東にある地点ほど早く朝を迎える。この差を国ごとに整理したのが標準時である。

■ なぜ15度で1時間なのか
地球は24時間で1回転＝360度回る。したがって
　360度 ÷ 24時間 ＝ 15度／時間
経度が15度ちがえば時刻は1時間ちがう。逆に、時差が1時間なら経度差は15度である。

■ 標準時子午線
国や地域ごとに基準となる経線を1本決め、その経線上の時刻をその国全体の時刻として使う。これを標準時という。
・日本……東経135度（兵庫県明石市）→ 世界標準時（経度0度）より 135÷15＝9時間進んでいる。
・イギリス……経度0度（本初子午線）。世界標準時の基準。

■ 計算の三ステップ
①二地点の経度差を求める
　同じ半球（東経どうし／西経どうし）……大きいほうから小さいほうを引く
　ちがう半球（東経と西経）……二つを足す
②経度差 ÷ 15 ＝ 時差（時間）
③東にあるほうが進んでいる。東の地点の時刻＝西の地点の時刻＋時差

例1）東京（東経135度）とロンドン（0度）
　経度差＝135−0＝135度 → 135÷15＝9時間。東京が9時間進んでいる。
　東京が1月5日午前9時なら、ロンドンは9時間戻して1月5日午前0時。

例2）東京（東経135度）とニューヨーク（西経75度）
　東経と西経なので足す。経度差＝135＋75＝210度 → 210÷15＝14時間。東京が14時間進んでいる。
　東京が1月5日午後8時なら、ニューヨークは14時間戻して1月5日午前6時。

例3）東京（東経135度）とカイロ（東経30度）
　同じ東経なので引く。経度差＝135−30＝105度 → 105÷15＝7時間。東京が7時間進んでいる。

★ ポイント：東経と西経がまざったら足す、そろっていたら引く。これを取りちがえるのが最大の失点原因である。`,
