        body: `■ 複数の標準時を持つ国
国土が東西に広い国は、1つの標準時ではくらしに合わなくなるため複数の標準時を設ける。
・ロシア……国土が東西に約170度にわたり、11の標準時を使う。
・アメリカ（本土）……東部・中部・山岳部・太平洋の4つ（アラスカ・ハワイを含めるとさらに増える）。
・カナダ……6つ。
・オーストラリア……3つ。

■ 広くても標準時が1つの国
中国は東西におよそ60度以上の広がりがあるが、標準時は北京付近の東経120度に統一されている（1つだけ）。そのため西部のウルムチでは、時計の上での日の出が朝の9時ごろになる。国土の広さと標準時の数は必ずしも対応しないことを示す例として、入試でよく取り上げられる。

■ 15度の倍数でない標準時
インドは東経82.5度を標準時子午線としており、世界標準時より5時間30分進んでいる（82.5÷15＝5.5）。ネパールは5時間45分。「時差は必ず1時間単位」ではない。

■ サマータイム（夏時間）
ヨーロッパやアメリカの一部では、夏の間だけ時計を1時間進める制度をとっている。この期間は計算上の時差から1時間ずれるため、問題文に「サマータイムは考えない」と断りが入るのがふつうである。断りがなければ考えないでよい。

■ 経度から標準時を逆算する
例）ある都市の時刻が日本より6時間遅れている。この都市の標準時子午線は東経何度か。
　時差6時間 → 経度差 6×15＝90度。日本より遅れている＝西にある。
　135−90＝45 → 東経45度。

⚠ 注意：問題文の「〜より進んでいる／遅れている」は必ず主語を確認する。「日本が9時間進んでいる」と「日本が9時間遅れている」では答えが18時間ずれる。`,
