　答え：1月10日午後2時（出発した日の午後に着く）

例2）ロンドン（0度）を2月5日午後1時に出発、飛行時間12時間で東京へ。到着時の日本時間は。
　①ロンドン時間での到着＝2月5日13時＋12時間＝2月6日午前1時
　②時差＝135÷15＝9時間、東京が進んでいる
