        heading: '五つの気候帯と分布の規則',
        body: `気温と降水量の組み合わせで、世界の気候は大きく五つに分けられる。

■ 熱帯（最寒月の平均気温が18℃以上）
一年中高温。熱帯雨林気候（年中多雨）とサバナ気候（雨季と乾季がある）に分かれる。赤道を中心に南北およそ20度までの範囲。

■ 乾燥帯（降水量が蒸発量より少ない）
砂漠気候（年降水量おおむね250mm未満）とステップ気候（短い雨季があり丈の短い草原）。緯度20〜30度付近に多い。これは赤道で上昇した空気が緯度20〜30度で下降して乾いた高気圧をつくるためで、サハラ砂漠・アラビア半島・オーストラリア内陸部が代表例である。

■ 温帯（最寒月がおおむね−3〜18℃）
温暖湿潤気候・西岸海洋性気候・地中海性気候の三つ。緯度30〜50度付近。世界の人口が最も集中する。

■ 冷帯・亜寒帯（最寒月が−3℃未満で、最暖月が10℃以上）
夏と冬の気温差が非常に大きい。タイガと呼ばれる針葉樹林が広がる。北緯40度以北のユーラシア・北アメリカにのみ分布する。

■ 寒帯（最暖月が10℃未満）
ツンドラ気候（最暖月0〜10℃、夏に地表の氷がとけてコケ類が育つ）と氷雪気候（最暖月0℃未満、一年中氷雪）。

■ 高山気候
低緯度でも標高が高ければ気温が下がる。標高100mにつき気温はおよそ0.6℃下がるので、赤道直下でも標高4,000m級の高地は涼しい。アンデス山脈やチベット高原が代表例。

★ ポイント：陸地に占める割合は乾燥帯が最大（約26%）で、温帯は約13%しかない。日本の常識が世界の標準ではないことを数字で確認しておく。`,
