        heading: '緯度だけでは決まらない——三つの修正要素',
        body: `気候帯は緯度でおおまかに決まるが、実際の分布は次の三つでずれる。

■ ①海流と風
暖流の上を吹いてきた風は暖かく湿った空気を運び、寒流の上を吹いてきた風は冷たく乾いた空気を運ぶ。
例）ヨーロッパ西岸……暖流の北大西洋海流＋偏西風で、北緯50度をこえても冬が温暖（西岸海洋性気候）。
例）南アメリカ西岸のアタカマ砂漠……寒流のペルー海流の影響で、海のそばなのに世界有数の乾燥地になっている。

■ ②大陸の東岸か西岸か
中緯度では偏西風（西から東へ吹く風）が卓越する。
・大陸西岸……海からの風が入るので年較差が小さく、降水も年間を通じて平均的（西岸海洋性気候）。
・大陸東岸……大陸内部からの空気の影響を受けやすく年較差が大きい。さらに季節風（モンスーン）の影響で夏に降水が集中する（温暖湿潤気候）。
日本が同緯度のヨーロッパより夏暑く冬寒いのは、この東岸・西岸のちがいによる。

■ ③標高
気温は標高100mにつき約0.6℃下がる。
例）標高3,400mのラパス（ボリビア）は南緯16度の低緯度にありながら年平均気温が10℃前後で、赤道直下でも常春の気候になる。

■ 南半球のちがい
・季節が逆……1月が夏、7月が冬。
・冷帯がない……南緯50〜70度にはほとんど陸地がないため、冷帯にあたる気候区が事実上存在しない。
・海洋の割合が大きいため、全体に年較差が小さい。

⚠ 注意：「赤道に近い＝暑い」は原則としては正しいが、標高（高山気候）と寒流（西岸の砂漠）という二つの例外がある。入試ではこの例外がねらわれる。`,
