        body: `■ 食
宗教ごとの食のきまりは、そのまま食品産業と観光に影響する。
・イスラム教……豚肉と酒を避ける。ハラール認証食品の市場は世界的に拡大しており、日本の食品メーカーも認証取得を進めている。豚由来のゼラチンや調理油にも配慮が必要。
・ヒンドゥー教……牛肉を避ける。菜食主義者も多く、インドの飲食店は菜食（ベジタリアン）用と非菜食用でメニューや厨房を分けていることがある。
・ユダヤ教……コーシャの規定。
・仏教……本来は殺生を戒め、僧は肉食を避ける。日本の精進料理はその流れをくむ。

■ 衣服
・イスラム教の女性が髪や体をおおう衣服（ヒジャブ・チャドル・ニカブなど）。地域と国の制度によって着用の程度は大きく異なる。
・シク教（インドのパンジャブ地方）の男性はターバンを巻き、ひげや髪を切らない。
・仏教の僧の袈裟、キリスト教の聖職者の祭服。

■ 暦と休日
・キリスト教圏……日曜日が休日。クリスマス（12月25日）、イースター（復活祭）。
・イスラム教圏……金曜日に集団礼拝。木・金や金・土を休日とする国が多い。イスラム暦は太陰暦なので、ラマダーンなどの行事は太陽暦に対して毎年約11日ずつ早まる。
・ヒンドゥー教……ディワリ（光の祭り）などの祭日。

■ 観光と国際交流への影響
訪日外国人が増えるなかで、日本の空港・駅・ホテルには礼拝室が整備され、ハラール対応のレストランが増えた。表示を多言語化するだけでなく、原材料や調理法まで踏み込んで示すことが求められている。

■ 宗教と対立
宗教のちがいそのものが対立の原因になるわけではないが、資源・領土・歴史的経緯と結びついたとき、対立の目印として働くことがある。北アイルランド問題（カトリックとプロテスタント）、パレスチナ問題（ユダヤ教とイスラム教）、カシミール問題（ヒンドゥー教とイスラム教）などが例である。多民族・多宗教の社会では、政教分離と信教の自由の保障が重要になる。

⚠ 注意：「宗教が原因で戦争が起きる」と単純化して書くと減点されやすい。土地・資源・歴史的経緯といった要素と結びついていることまで書くと評価される。`,
