        body: `世界の言語地図は、16〜20世紀のヨーロッパによる植民地支配の跡をほぼそのまま示している。

■ ラテンアメリカ
・スペイン語……メキシコ、コロンビア、アルゼンチン、ペルー、チリなど大部分の国。スペインの植民地だったため。
・ポルトガル語……ブラジル。1494年のトルデシリャス条約で南アメリカ東部がポルトガルの領分と定められ、そのままポルトガルの植民地になったため。ラテンアメリカで唯一の例外として頻出。
・フランス語……ハイチ、ギアナ。英語……ジャマイカ、ガイアナ。
「ラテンアメリカ」という呼び名自体が、ラテン系の言語（スペイン語・ポルトガル語）が使われる地域という意味である。

■ アフリカ
・フランス語……アルジェリア、セネガル、コートジボワール、コンゴ民主共和国など西・中央アフリカに多い。
・英語……ナイジェリア、ガーナ、ケニア、南アフリカ、ウガンダなど。
・ポルトガル語……アンゴラ、モザンビーク。
・アラビア語……北アフリカ（エジプト・リビア・モロッコなど）。

アフリカの多くの国は、国内に数十から数百の民族と言語をかかえている。そのうちの一つを公用語にすると他の民族が不利になるため、あえて中立な旧宗主国の言語を公用語とし、民族どうしの共通語として使っている。エチオピアのように植民地化を免れた国では、現地の言語（アムハラ語）が公用語になっている。

■ アジア・太平洋
・英語……インド（準公用語）、フィリピン、シンガポール、マレーシア（英語は広く通用）、オーストラリア、ニュージーランド。
・スペイン語……フィリピンは長くスペイン領だったが、その後アメリカの統治下に入ったため現在の公用語はフィリピノ語と英語である。

■ インドの言語事情
連邦の公用語はヒンディー語、準公用語が英語。ほかに州ごとの公用語が22言語も憲法で認められている。紙幣にはヒンディー語と英語のほか、多数の言語で額面が記されている。英語が広く使われることが、ICT産業でアメリカ企業の業務を請け負ううえで大きな強みになった。

⚠ 注意：「ブラジルの公用語はスペイン語」は代表的な誤答。南アメリカでブラジルだけがポルトガル語である理由（ポルトガルの植民地）まで書けるようにしておく。`,
