        heading: '人口・宗教・ICT産業',
        body: `■ 人口
インドの人口は約14億3千万人で、2023年に中国を抜いて世界第1位になった。年齢別人口構成は若い世代が多い富士山型に近く、今後も労働力人口が増える見通しで、これが経済成長の強みとされる（人口ボーナス）。一方で、雇用の創出、教育、都市のインフラ整備が追いつくかが課題である。

■ 宗教
・インド……ヒンドゥー教 約80%、イスラム教 約14%、そのほかシク教・キリスト教・仏教・ジャイナ教。
・パキスタン、バングラデシュ……イスラム教。
・スリランカ、ブータン、ネパールの一部……仏教（ネパールはヒンドゥー教が多数）。
1947年のイギリスからの独立の際、ヒンドゥー教徒が多い地域はインド、イスラム教徒が多い地域はパキスタン（当時は東西に分かれ、東は1971年にバングラデシュとして独立）として分離独立した。その過程で大規模な人の移動と衝突が起き、北部のカシミール地方の帰属をめぐる対立は現在も続いている。

■ カースト
ヒンドゥー教と結びついた身分の考え方。憲法は身分による差別を禁止しており、進学や就職で不利な立場の人々に一定の枠を確保する制度もある。しかし結婚や地域社会の慣習としては影響が残っている。ICT産業は歴史の新しい職種でカーストの枠組みに縛られにくく、能力次第で高い収入を得られる道として若者に人気がある、という指摘もある。

■ ICT（情報通信技術）産業
インド南部のベンガルール（旧称バンガロール）を中心に、ソフトウェア開発・システム運用・コールセンターなどの産業が急成長した。強みは次の四つである。
①英語が広く使われる（旧イギリス領で、英語が準公用語）
②数学・理数系の教育水準が高く、理工系の技術者が豊富
③アメリカと約12時間の時差があり、アメリカが夜のあいだにインドで作業を進めて翌朝に納品できる（24時間開発）
④賃金がアメリカより低く、人件費を抑えられる
インド工科大学（IIT）は世界的に評価が高く、多くの卒業生がアメリカのIT企業で活躍している。

■ そのほかの産業
自動車、医薬品（後発医薬品の生産で世界有数）、鉄鋼。近年はスマートフォンの生産拠点としても存在感を増している。

⚠ 注意：時差の説明を「時差があるから便利」で終わらせず、「アメリカの夜＝インドの昼を利用して作業を引き継ぐ」という具体的なしくみまで書けるようにする。時差は東経82.5度を標準時とするインドと、西経75度を標準時とするアメリカ東部で約10時間30分（サマータイム時は約9時間30分）である。`,
