        body: `■ 石油はどこにあるか
石油は、大昔の海に堆積した生物の遺骸が地層の中で変化してできたもので、背斜構造など特定の地質条件のところにたまる。ペルシャ湾岸はその条件がそろった世界最大級の油田地帯である。
・おもな産油国……サウジアラビア、イラク、イラン、クウェート、アラブ首長国連邦、カタール
・世界の原油の確認埋蔵量のうち、中東地域が占める割合はおよそ半分にのぼる。
・西アジア以外の主要産油国……アメリカ（シェールオイル）、ロシア、カナダ、ブラジル、ナイジェリア。産出量ではアメリカ・サウジアラビア・ロシアが上位を占める。

■ OPEC（石油輸出国機構）
1960年、産油国が石油の価格や生産量を自分たちで決める力を持つために結成した。それまでは欧米の国際石油資本（石油メジャー）が価格決定権を握っていた。
・1973年、第四次中東戦争を背景にOPEC諸国が原油価格を大幅に引き上げ、輸出を制限したため、世界経済が混乱した。これが第一次石油危機（オイルショック）である。日本では物価が急上昇し、高度経済成長が終わるきっかけになった。
・こうした、自国の資源は自国で管理し利益を得ようとする動きを資源ナショナリズムという。

■ 産油国の課題
・モノカルチャー的な経済……輸出の大半を原油が占めるため、国際価格が下がると国家財政が一気に悪化する。
・資源の有限性……いつかは枯渇する。また世界の脱炭素の流れで需要が減る可能性がある。
・そのため各国は産業の多角化を進めている。アラブ首長国連邦のドバイは、貿易港・国際空港のハブ機能、金融、観光に投資し、原油に頼らない経済への転換を進めた。サウジアラビアも観光や再生可能エネルギーへの投資を拡大している。
・外国人労働者……建設や家事労働を南アジア・東南アジアからの出稼ぎ労働者に依存しており、労働環境の改善が課題となっている。

★ ポイント：「石油危機（1973年）→ 資源ナショナリズム → 日本の省エネ・産業構造の転換」という因果関係は、歴史・公民とも結びつく重要な流れである。`,
