        heading: '高緯度なのに温暖な理由',
        body: `■ 緯度を確認する
ロンドン 北緯51.5度／パリ 北緯48.9度／ベルリン 北緯52.5度／ローマ 北緯41.9度。
日本と比べると、札幌が北緯43.1度、稚内が北緯45.4度である。つまりロンドン・パリ・ベルリンはいずれも稚内より北にある。それでも冬の平均気温はロンドンで約5℃、稚内で約−4℃と、ロンドンのほうが9℃も高い。

■ 二つの要因
①北大西洋海流（暖流）
　メキシコ湾流の続きで、大西洋を北東へ流れる暖流。低緯度の熱を高緯度へ運び、ヨーロッパ西岸の海水温を高く保つ。
②偏西風
　緯度30〜60度の中緯度帯を、西から東へ一年中吹く風。暖流の上を通ってきた暖かく湿った空気を、大陸の内部まで運びこむ。
この二つがそろって初めて、高緯度での温暖な冬が実現する。暖流だけあっても風が陸へ運ばなければ内陸は暖まらない。

■ 同じ緯度の大陸東岸との比較
カナダのウィニペグ（北緯約50度）は1月の平均気温が約−16℃、ロンドン（北緯約51.5度）は約5℃で、その差は約21℃。夏（7月）は両者とも18〜20℃前後でほとんど変わらない。つまり差が出るのは冬だけである。これは、偏西風の風上に海があるか大陸があるかの違いによる。大陸西岸は海が風上、大陸東岸は大陸が風上になる。

■ 東へ行くほど大陸性
偏西風は西から吹くので、大西洋から遠ざかる東ヨーロッパ・ロシアへ行くほど海の影響が弱まり、年較差が大きくなる。
・ロンドン（西岸海洋性）年較差 約13℃
・ベルリン（西岸海洋性〜大陸性の移行帯）年較差 約19℃
・モスクワ（冷帯）年較差 約25℃
西から東へ横断すると、気候が段階的に大陸性へ変わっていくのがわかる。

★ ポイント：「暖流＋偏西風」の二点セットで答える。片方だけだと説明として不十分になる。`,
