        heading: '独立と、その後の歩み',
        body: `■ 独立の流れ
第二次世界大戦後、アジアに続いてアフリカでも独立の動きが強まった。
・1957年 ガーナが、サハラ以南のアフリカで最初に独立（イギリスから）。
・1960年 一年間に17の国が独立し、「アフリカの年」と呼ばれる。
・1960年代を通じて多くの国が独立を達成した。
・1975年 アンゴラ・モザンビーク（ポルトガルから）。
・1990年 ナミビア。
・2011年 南スーダンがスーダンから分離独立し、アフリカで最も新しい国となった。

■ 独立後の困難
・経済……植民地時代に整えられたのは、特定の一次産品を宗主国へ運ぶための鉄道と港だけで、国内をつなぐ交通網や工業は育っていなかった。独立してもモノカルチャー経済が続いた。
・政治……民族対立を背景とする内戦やクーデターが繰り返された国もある。ルワンダ（1994年）、ソマリア、コンゴ民主共和国などで大規模な犠牲が出た。
・教育・医療……人材と資金の不足。

■ 地域協力
・OAU（アフリカ統一機構、1963年）を発展させ、2002年にAU（アフリカ連合）が発足した。55の国・地域が加盟し、EUをモデルに政治的・経済的な統合、紛争の予防と解決をめざしている。
・2021年にはAfCFTA（アフリカ大陸自由貿易圏）が動き出し、域内の関税撤廃による経済成長が期待されている。

■ 南アフリカ共和国とアパルトヘイト
・少数の白人が政治・経済を握り、人種によって居住地・教育・職業・結婚を分離するアパルトヘイト（人種隔離政策）を法律で定めていた。
・国際社会からの経済制裁と国内の抵抗運動により、1991年に関連法が撤廃され、1994年の全人種参加の選挙でネルソン=マンデラが大統領に選出された。
・現在も経済的な格差は大きく残っており、政策の廃止と現実の平等は別の問題であることを示している。
・南アフリカは金・ダイヤモンド・プラチナ・クロムなどの鉱産資源に恵まれ、アフリカ有数の工業国でもある。BRICSの一員でもある。

⚠ 注意：「アパルトヘイトは現在も続いている」は誤り。1991年に法律上は廃止されている。ただし経済格差という形で影響が残っている、と書き分ける。`,
