        heading: '農産物——プランテーション作物の産地',
        body: `アフリカの輸出向け農産物の多くは、植民地時代に開かれたプランテーションを起源とする。

■ カカオ豆
チョコレートの原料。高温多雨の熱帯で、直射日光を避けた環境で育つ。
・コートジボワール……世界第1位、世界の約4割。
・ガーナ……第2位、世界の約2割。
この2か国だけで世界のおよそ6割を占め、ギニア湾岸に極端に集中している。
生産国では、カカオ豆をチョコレートに加工する工程はほとんど行われず、原料のまま安く輸出される。付加価値の大きな加工・販売の利益は消費国の企業に渡るという構造があり、これを是正するために、生産者に適正な価格を支払うフェアトレードの取り組みが広がっている。児童労働の問題も指摘されている。

■ コーヒー
エチオピアが原産地とされる。エチオピア高原・ケニア・タンザニア・ウガンダなど東アフリカの高原地帯で栽培される。高地の涼しい気候と適度な降水が適する。

■ 茶
ケニアが世界有数の輸出国。赤道直下だが標高1,500〜2,000mの高地で、涼しい気候を利用して栽培する。

■ 落花生・綿花
セネガル・スーダンなどで栽培される。落花生はサヘル周辺の乾燥に強い作物として重要である。

■ 自給用の作物
輸出用作物のかげで、住民の食料となるキャッサバ・ヤムいも・とうもろこし・ミレット（雑穀）なども広く栽培されている。しかし輸出用作物に良い農地が使われるため、食料を輸入に頼る国もある。

★ ポイント：カカオ＝ギニア湾岸（西アフリカ・低地）、コーヒーと茶＝東アフリカの高原、という産地の対比で覚える。`,
