        body: `■ 人口の急増
アフリカの人口は約15億人で、世界の約2割を占める。出生率が高く、世界で最も速いペースで増加しており、国連の予測では2050年に約25億人に達するとされる。今世紀後半には、世界の人口増加のほとんどをアフリカが占めるとみられている。
・年齢別人口構成は、若い世代が非常に多い富士山型（ピラミッド型）。
・多くの若者は将来の労働力・消費者として経済成長の原動力になりうる（人口ボーナス）が、それには教育と雇用の整備が前提となる。

■ 食料と水
人口増加に食料生産が追いつかず、栄養不足に苦しむ人が多い地域がある。干ばつが重なると飢餓が発生する。安全な水を得られない人も多く、水くみは子ども（特に女子）の仕事となって就学の妨げになることがある。

■ 都市問題
農村での生活が成り立たなくなった人々が都市へ流入し、ラゴス（ナイジェリア）・カイロ（エジプト）・キンシャサ（コンゴ民主共和国）・ナイロビ（ケニア）などが急激に巨大化した。
・住宅・上下水道・電気・ごみ処理が追いつかず、スラム（不良住宅地区）が広がる。
・十分な雇用がないため、路上での物売りなどインフォーマルセクター（正規に登録されていない仕事）で生計を立てる人が多い。

■ 教育・保健
・初等教育の就学率は大きく改善したが、中等・高等教育、女子の就学、教員不足には課題が残る。
・感染症対策（マラリア・HIV／エイズ）や、乳幼児死亡率の低減が進められている。

■ 新しい動き
・携帯電話の普及……固定電話の回線を敷かないまま携帯電話が一気に広まった。ケニアで始まった携帯電話による送金サービス（モバイルマネー）は、銀行口座を持たない人々の決済・送金を可能にし、経済活動を大きく変えた。段階を飛ばして最新技術が普及する現象をリープフロッグ（かえるとび）型発展という。
・再生可能エネルギー……日照に恵まれることから太陽光発電の導入が進む。送電網のない村でも、小規模な太陽光と蓄電池で電気が使えるようになった。
・国際協力……日本はTICAD（アフリカ開発会議）を1993年から主催し、インフラ整備・人材育成・保健分野で協力を進めている。青年海外協力隊の派遣も行われている。

⚠ 注意：アフリカを「貧しく遅れた大陸」と一括りにする記述は不正確である。国による差が非常に大きく、都市部では急速な経済成長とデジタル化が進んでいる。統計と具体例で語ること。`,
