        body: `アメリカの農業は、その土地の気候と土壌に最も適した作物を選ぶ適地適作を原則とし、地域ごとに専門化している。

■ 西経100度線
年降水量500mmのおよその境で、土地利用の分かれ目になる。
・西……乾燥。放牧（肉牛）と、地下水を利用した灌漑による小麦・飼料作物の栽培。
・東……湿潤。とうもろこし・大豆・小麦・綿花の栽培。

■ 主な農業地域
・コーンベルト……五大湖の南、アイオワ州・イリノイ州を中心とする地域。肥沃なプレーリー土と夏の高温多雨がとうもろこし栽培に適する。近年は大豆との輪作が進み、実質的には「コーン＆ソイビーンベルト」になっている。とうもろこしは食用より家畜の飼料とバイオエタノールの原料に多く使われる。
・酪農地帯……五大湖周辺と北東部。冷涼で穀物栽培に不利なうえ、ニューヨークなどの大消費地に近いため乳製品の生産が有利。
・小麦地帯……グレートプレーンズ。北部（ノースダコタ・モンタナ）は春に種をまく春小麦、南部（カンザス・オクラホマ）は秋にまいて越冬させる冬小麦。緯度によって作型が分かれる。
・綿花地帯（コットンベルト）……南部。かつて奴隷労働に支えられた綿花栽培の中心。現在は大豆・とうもろこし・落花生への転換が進み、綿花の中心は西のテキサス・カリフォルニアへ移動した。
・地中海式農業……カリフォルニア。ぶどう（ワイン）・オレンジ・レモン・アーモンド。灌漑が不可欠である。
・放牧……ロッキー山脈周辺、テキサス。肉牛をフィードロット（肥育場）に集め、とうもろこしなどの飼料で短期間に太らせてから出荷する。

■ 生産量
とうもろこしの生産量は世界第1位で年間約3億5千万トン。大豆・小麦・綿花も世界有数である。とうもろこし・大豆・小麦の輸出量では世界の上位を占め、「世界の食料庫」「世界のパンかご」と呼ばれる。

★ ポイント：「西経100度線＝年降水量500mm＝放牧と農耕の境」は地図問題で頻出。線の位置を地図帳で確認しておく。`,
