        body: `■ なぜ五大湖周辺で工業が発達したか
19〜20世紀の重工業は、重くかさばる原料を運ぶコストが立地を決めた。
・石炭……アパラチア山脈の炭田。
・鉄鉱石……五大湖西部のメサビ鉄山。
・輸送……五大湖と運河・河川による安い水運で、両者を低コストで結べた。
この条件がそろったため、ピッツバーグ（鉄鋼）、クリーブランド・シカゴ（鉄鋼・機械）、デトロイト（自動車）が発展した。

■ 大量生産方式
デトロイトでは20世紀初め、ベルトコンベアによる流れ作業で自動車を大量生産する方式が確立された。安価な自動車が普及し、アメリカ社会は自動車中心の生活へ変わっていった。郊外に住宅地が広がり、大型のショッピングセンターが道路沿いに立地するという都市の形も、ここから生まれた。

■ 衰退——ラストベルト
1970年代以降、次の理由で五大湖周辺の工業は衰退した。
・日本・ドイツ、のちに韓国・中国の企業との競争に敗れた。
・設備が古くなり、更新に費用がかかった。
・労働組合が強く賃金水準が高かった。
・エネルギーが石炭から石油・天然ガスへ移り、炭田に近い利点が失われた。
工場の閉鎖が相次ぎ、失業と人口流出が続いた。さびついた工業地帯という意味でラストベルト（Rust Belt）と呼ばれる。デトロイトは2013年に財政破綻した。

■ 再生の試み
自動車産業は生産拠点を南部へ移し、また日本メーカーもアメリカ国内に工場を建てて生産している（現地生産）。五大湖周辺では医療・教育・研究機関を核とした都市再生が進められている。

★ ポイント：「原料立地→原料の重要性低下→労働力・気候・研究環境で立地が決まる」という、工業立地の条件の変化として理解する。`,
