        body: `■ 成り立ち
・先住民……ネイティブアメリカン（インディアン）。ヨーロッパからの入植者に土地を奪われ、居留地へ強制的に移住させられた歴史を持つ。
・ヨーロッパ系……17世紀以降、イギリス・ドイツ・アイルランド・イタリア・東ヨーロッパから移住。
・アフリカ系……16〜19世紀に奴隷として連れてこられた人々の子孫。南部の綿花プランテーションで働かされた。1863年の奴隷解放宣言後も長く差別が続き、1950〜60年代の公民権運動を経て法的な平等が実現した。それでも所得や教育の格差は残っている。
・アジア系……19世紀の中国系・日系に始まり、近年はインド・フィリピン・ベトナム・韓国からの移民が増加している。
・ヒスパニック……メキシコ・中米・カリブ海諸国から来たスペイン語を話す人々。人口比で最も増加が著しく、カリフォルニア・テキサス・フロリダ・ニューヨークに多い。

■ ヒスパニックの増加が社会に与える影響
・スペイン語が第二の言語として定着し、公共の表示・放送・商品パッケージが二言語表記になっている地域が多い。
・農業・建設・サービス業で重要な労働力となっている。
・一方で、不法移民や国境管理をめぐる政治的な対立が続いている。

■ サラダボウル
かつては、多様な移民が溶け合って一つのアメリカ人になるという意味で「人種のるつぼ（メルティングポット）」と表現された。しかし実際には、それぞれの民族が固有の言語・宗教・食文化を保ちながら共存している面が強いため、近年は素材が混ざりつつ個性を残す「サラダボウル」という表現が使われる。

■ 都市の構造
大都市では、都心部の治安や住環境の悪化を背景に富裕層が郊外へ移り住み、都心が空洞化する現象（インナーシティ問題）が起きた。近年は都心の再開発が進み、人が戻る動きも見られる。

★ ポイント：「るつぼ」から「サラダボウル」への言い方の変化は、多文化共生の考え方の変化を表す。理由を説明できるようにする。`,
