        heading: '歴史と民族の構成',
        body: `■ 先住民の文明
・インカ帝国……15〜16世紀、アンデス高地に栄えた。マチュピチュの遺跡、精巧な石組みの建築、じゃがいも・とうもろこしの栽培、リャマ・アルパカの飼育で知られる。文字を持たず、キープ（結縄）で記録した。
・低地にはほかにも多くの先住民の社会があった。

■ ヨーロッパによる征服と植民地化
・1494年 トルデシリャス条約……スペインとポルトガルが「新大陸」の領分を、大西洋上に引いた線で分けた。この線の東側が現在のブラジルにあたり、ポルトガル領となった。南アメリカでブラジルだけがポルトガル語を使う理由である。
・16世紀にスペインがインカ帝国を滅ぼし、銀山（ポトシ）を開発して大量の銀をヨーロッパへ持ち帰った。
・先住民は強制労働と、ヨーロッパから持ちこまれた感染症によって人口が激減した。
・労働力を補うため、アフリカから多数の人々が奴隷として連れてこられた。特にブラジル北東部のさとうきびプランテーションで働かされた。

■ 独立
19世紀初め、ナポレオン戦争によるスペイン本国の混乱を機に、各地で独立運動が起こり、1810〜20年代にかけて多くの国が独立した。ブラジルは1822年にポルトガルから独立した。

■ 現在の民族構成
・先住民（インディオ）……ボリビア・ペルー・エクアドルに多い。ボリビアでは人口の多数を占める。
・ヨーロッパ系……アルゼンチン・ウルグアイに多い。
・アフリカ系……ブラジル北東部、カリブ海沿岸。
・メスチソ……先住民とヨーロッパ系の混血。多くの国で人口の中心を占める。
・ムラート……ヨーロッパ系とアフリカ系の混血。
・日系人……ブラジルには20世紀初めからの移民の子孫が約200万人暮らすとされ、日本国外で最大の日系社会を形成している。ペルーにも多い。1990年代以降、その子孫が日本へ働きに来る動きもあった（在日ブラジル人）。

■ 言語と宗教
・ブラジルはポルトガル語、そのほかの多くの国はスペイン語。ガイアナは英語、スリナムはオランダ語、仏領ギアナはフランス語。
・宗教はカトリックが中心。先住民やアフリカの信仰と混ざり合った独自の文化（ブラジルのカーニバル、サンバなど）も生まれた。

⚠ 注意：「ラテンアメリカ」はメキシコ以南のアメリカ大陸全域（中央アメリカ・カリブ海諸国を含む）を指す。「南アメリカ」とは範囲が異なるので、設問の語をよく読むこと。`,
