        body: `■ 急激な都市化
南アメリカは、発展途上地域のなかでは都市人口の割合が高く、多くの国で8割前後に達する。20世紀後半、農村での生活が成り立たなくなった人々が仕事を求めて都市へ流れこんだ。しかし、都市の側には十分な雇用も住宅もなかった。

■ ファベーラ（スラム）
リオデジャネイロなどの都市の斜面や周辺部に、簡素な住宅が密集する地区が形成された。ブラジルではファベーラと呼ばれる。
・上下水道・電気・ごみ収集などのインフラが十分でない。
・急斜面に建てられているため、大雨による土砂崩れの危険が高い。
・治安の問題を抱える地区もある。
・行政による住環境の改善、ケーブルカーやエスカレーターの設置による交通の確保など、改善の取り組みも進められている。

■ プライメートシティ
一国のなかで、第2位の都市を大きく引き離して人口が集中する都市を首位都市（プライメートシティ）という。政治・経済・文化の機能が一つの都市に集中し、地方との格差が広がる。ペルーのリマ、アルゼンチンのブエノスアイレス、チリのサンティアゴがその例である。

■ 背景にある格差
南アメリカでは、植民地時代に形成された大土地所有制（アシエンダ・ファゼンダ）の影響が残り、土地の所有が一部の人に集中している国が多い。土地を持たない農民が都市へ流入する構図が、都市問題の背景にある。所得の格差も大きく、同じ都市の中に高級住宅街とスラムが隣り合う光景が見られる。

■ 持続可能な開発
「将来の世代の必要を損なわずに、現在の世代の必要を満たす開発」を持続可能な開発という。1992年、ブラジルのリオデジャネイロで国連環境開発会議（地球サミット）が開かれ、気候変動枠組条約と生物多様性条約が結ばれた。開発と環境保全の両立をどう図るかという問いは、南アメリカが世界に投げかけている課題でもある。
2015年に国連で採択されたSDGs（持続可能な開発目標）にも、陸の豊かさを守ること、住み続けられるまちづくりといった目標が含まれている。

⚠ 注意：熱帯林の保全を「発展途上国が森を切るのが悪い」と一方的に書くのは誤り。切られた森の産物（大豆・牛肉・木材）を消費しているのは先進国であり、消費国の責任にも触れると評価される。`,
