        heading: '三つの島々とオセアニアの自然',
        body: `■ 三つの区分
太平洋に散らばる島々は、名前の意味から区分を覚えられる。
・ミクロネシア……「小さい島々」の意味。赤道以北、フィリピンの東。パラオ、ミクロネシア連邦、マーシャル諸島、グアム（アメリカ領）。
・メラネシア……「黒い島々」の意味。赤道以南、オーストラリアの北東。パプアニューギニア、ソロモン諸島、フィジー、バヌアツ、ニューカレドニア（フランス領）。
・ポリネシア……「多くの島々」の意味。ハワイ・ニュージーランド・イースター島を結ぶ三角形の内側。トンガ、サモア、タヒチ（フランス領）、ツバル。

■ 島の成り立ち
①火山島……海底火山の噴火でできた島。標高が高く、水も土壌もあり農業が可能。ハワイ諸島、タヒチ、フィジーの一部。
②サンゴ礁の島……サンゴの遺骸が積み重なってできた島。標高が数メートルしかない。環礁（リング状に島が並び、内側にラグーン＝礁湖がある地形）が典型。ツバル、マーシャル諸島、キリバス。

■ 海面上昇の問題
地球温暖化により海水が膨張し、氷河や氷床がとけて海面が上昇している。標高の低いサンゴ礁の島国では、
・高潮による浸水
・海水が地下水に混じって飲み水と農地が塩害を受ける
・海岸の侵食
といった被害がすでに起きている。ツバルやキリバスは、国土そのものが失われる可能性に直面しており、国際会議で温室効果ガスの削減を強く訴えている。二酸化炭素の排出量がごくわずかな国が、最も大きな被害を受けるという不公平が問題となっている。

■ グレートバリアリーフ
オーストラリア北東岸に約2,000kmにわたって連なる世界最大のサンゴ礁。世界自然遺産に登録されている。海水温の上昇によりサンゴが白化して死滅する現象が繰り返し起きており、保全が課題となっている。

★ ポイント：「ミクロ＝小さい」「メラ＝黒い」「ポリ＝多い」と語の意味で覚えると、三つの区分を取りちがえない。`,
