        heading: '鉱産資源と露天掘り',
        body: `オーストラリアは古い安定した陸塊が広く、鉱産資源に恵まれている。産地と資源の対応が入試で頻出である。

■ 主な資源と産地
・鉄鉱石……北西部のピルバラ地区（マウントホエールバックなど）。世界有数の産出量で、日本の主要な輸入先である。
・石炭……東部（ニューサウスウェールズ州・クイーンズランド州）。原料炭・一般炭とも輸出。
・ボーキサイト……北部（ヨーク岬半島のウェイパなど）。アルミニウムの原料。
・金……西部（カルグーリー）。
・ウラン……北部・南部。
・液化天然ガス……北西部の海底ガス田。近年輸出が急増した。
・レアアース・リチウム……電池や磁石の材料として重要性が高まっている。

■ 露天掘り
地表から階段状に掘り下げて鉱石を採る方法。坑道を掘る方式に比べて、大型のショベルとダンプトラックを使えるため生産性が高く、コストが安い。オーストラリアの鉄鉱石・石炭の多くはこの方法で採掘される。
一方、広い面積の地表を掘り返すため、跡地の環境回復が課題となる。採掘を終えた場所に土を戻して植生を回復させる取り組みが義務づけられている。

■ 輸送
鉱山から港まで専用の鉄道が敷かれ、長大な貨物列車で鉄鉱石が運ばれる。港からは大型のばら積み船で輸出される。日本・中国・韓国が主な輸出先である。

■ 日本との関係
日本は鉄鉱石・石炭・液化天然ガスの多くをオーストラリアから輸入している。距離が近く政治的にも安定しているため、資源の供給先として重要な位置を占める。日本からは自動車・機械類を輸出しており、資源と工業製品を交換する形の貿易になっている。

★ ポイント：「鉄鉱石＝北西部（ピルバラ）」「石炭＝東部」「ボーキサイト＝北部」。方角とセットで覚えると資源分布図の問題に強くなる。`,
